-- Replace plaintext api_key column with hashed key_hash and key_suffix

-- Create new table with hashed key columns
CREATE TABLE IF NOT EXISTS user_api_key_new (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL REFERENCES user(id) ON DELETE CASCADE,
    key_hash TEXT NOT NULL UNIQUE,
    key_suffix TEXT NOT NULL,
    name TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    last_used_at INTEGER,
    UNIQUE (user_id, name)
);

-- Copy existing rows, dropping the plaintext api_key
-- Existing keys become unusable and must be regenerated by the user.
-- This is acceptable as the feature is pre-production and no existing
-- deployments rely on user API keys. Application code handles hashing
-- for all newly created keys.
INSERT INTO user_api_key_new (id, user_id, key_hash, key_suffix, name, created_at, last_used_at)
SELECT id, user_id, '', '', name, created_at, last_used_at
FROM user_api_key;

DROP TABLE user_api_key;
ALTER TABLE user_api_key_new RENAME TO user_api_key;

CREATE INDEX IF NOT EXISTS idx_user_api_key_key_hash ON user_api_key(key_hash);
CREATE INDEX IF NOT EXISTS idx_user_api_key_user ON user_api_key(user_id);

